{"packet_id":"D026-01","doc_id":"D026","jurisdiction":"CA","category":"application_screening_fees","lifecycle":"enacted","title":"California application screening fee cap","requirement":"A landlord or agent may charge an application screening fee only up to actual out-of-pocket costs and never more than $30 per applicant, adjusted annually by the CPI. The landlord must give an itemized receipt and refund unused amounts.","key_value":"$30 per applicant, adjusted annually by CPI","coverage_conditions":"Applies to any owner of residential rental property and their agent who receives a request to rent, including guarantors and cosigners as applicants.","applicability":{"conditions":[],"per_tenancy":"Fee may be charged only when a rental unit is or will be available and the application is actually considered.","coverage_quotes":[]},"exemptions":"No refund is required for an applicant denied after consideration for not meeting the landlord's screening criteria. Federal or state housing assistance program rules on deposits and fees are not preempted.","penalty":null,"effective_date":"2026-01-01","valid_through":null,"citation":"Cal. Civ. Code § 1950.6","quoted_span":"In no case shall the amount of the application screening fee charged by the landlord or their agent be greater than thirty dollars ($30) per applicant.","interaction":"Does not preempt federal or state rules governing collection of deposits and fees under housing assistance programs.","relations":[],"confidence":0.95,"conflict_flag":false,"conflict_note":null}
{"packet_id":"D026-01","doc_id":"D026","jurisdiction":"CA","category":"screening_restrictions","lifecycle":"enacted","title":"California application screening process order","requirement":"A landlord charging a screening fee must consider completed applications in the order received under written screening criteria, approve the first applicant who meets them, and charge no fee until an application is considered.","key_value":null,"coverage_conditions":"Applies to any owner of residential rental property and their agent who receives a request to rent a residential housing unit.","applicability":{"conditions":[],"per_tenancy":"Applies when a landlord charges an application screening fee and screens applicants.","coverage_quotes":[]},"exemptions":null,"penalty":null,"effective_date":"2026-01-01","valid_through":null,"citation":"Cal. Civ. Code § 1950.6","quoted_span":"Completed applications are considered, as provided for in the landlord’s established screening criteria, in the order in which the completed applications were received. The landlord’s screening criteria shall be provided to the applicant in writing together with the application form.","interaction":null,"relations":[],"confidence":0.8,"conflict_flag":false,"conflict_note":null}
